-- N5 kanji: 79 cards, 8 days
insert into public.units (level, track, week, day, title, source)
select v.* from (values
  (5, 'kanji', 1, 1, 'Week 1 · Day 1', 'auto'),
  (5, 'kanji', 1, 2, 'Week 1 · Day 2', 'auto'),
  (5, 'kanji', 1, 3, 'Week 1 · Day 3', 'auto'),
  (5, 'kanji', 1, 4, 'Week 1 · Day 4', 'auto'),
  (5, 'kanji', 1, 5, 'Week 1 · Day 5', 'auto'),
  (5, 'kanji', 1, 6, 'Week 1 · Day 6', 'auto'),
  (5, 'kanji', 1, 7, 'Week 1 · Day 7', 'auto'),
  (5, 'kanji', 2, 1, 'Week 2 · Day 1', 'auto')
) v(level, track, week, day, title, source)
where not exists (select 1 from public.units x where x.level = 5 and x.track = 'kanji' and x.source = 'soumatome')
on conflict (level, track, week, day) do nothing;

